/*!50003 CREATE*/ /*!50017 DEFINER=`meowsysadmin`@`192.168.%`*/ /*!50003 TRIGGER `bi_categories_mysql57_guard` BEFORE INSERT ON categories FOR EACH ROW BEGIN
  IF (NEW.group_type IN ('product_type','lens_type','gender','frame_shape','material','collection')) IS FALSE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rule ck_categories_group_type failed'; END IF;
  IF (NEW.group_type <> 'product_type' OR NEW.code IN ('frame','lens','package')) IS FALSE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Rule ck_categories_product_kind failed'; END IF;
END */;;
